                        onReject: {
                            Task { await store.rejectProjectMergeCandidate(candidate.id) }
                        },
                        onDismiss: {
                            Task { await store.dismissProjectMergeCandidate(candidate.id) }
                        }
                    )
                }
            }
            .summarySurface()
        }
    }
}

